function validate([points]) {
  if (!Array.isArray(points) || points.length < 3 || points.length > 50) return 'points needs 3 to 50 points.';
  const seen = new Set();
  for (const point of points) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < -50 || v > 50)) return 'Coordinates are whole numbers from -50 to 50.';
    const key = point[0] + ',' + point[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  return null;
}

