function largestTriangleArea(points) {
  // Heron's formula in squared side lengths, 16 * area^2 = 4 * A * B - (A + B - C)^2, which stays exact for integers.
  const squared = (p, q) => (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2;
  let best = 0;
  for (const p of points)
    for (const q of points)
      for (const r of points) {
        if (p === q || q === r || p === r) continue;
        const A = squared(p, q), B = squared(q, r), C = squared(p, r);
        const sixteenAreaSquared = 4 * A * B - (A + B - C) ** 2;
        best = Math.max(best, Math.sqrt(Math.max(0, sixteenAreaSquared)) / 4);
      }
  return best;
}

