function generate(rand, size) {
  const n = size === 'large' ? 50 : 3 + Math.floor(rand() * 6);
  // Small inputs sometimes lie on one line, where every triangle has area 0.
  const line = size === 'small' && rand() < 0.2;
  const span = size === 'large' || line || rand() < 0.4 ? 50 : 3;
  const seen = new Set();
  const points = [];
  const slope = Math.floor(rand() * 5) - 2;
  while (points.length < n) {
    const x = Math.floor(rand() * (2 * span + 1)) - span;
    const y = line ? slope * x : Math.floor(rand() * (2 * span + 1)) - span;
    if (y < -50 || y > 50 || seen.has(x + ',' + y)) continue;
    seen.add(x + ',' + y);
    points.push([x, y]);
  }
  return [points];
}
